public class UrlBuilder {
    private String url;
    private boolean hasQuery;

    public UrlBuilder(String url) {
        this.url = url;
        this.hasQuery = false;
    }

    public void addQueryParameter(String key, String value) {
        if (!hasQuery) {
            url += "?";
            hasQuery = true;
        }
        url += key + "=" + value + "&";
    }

    public String build() {
        if (url.contains("?")) {
            return url.substring(0, url.lastIndexOf('?')) + "#fragment";
        } else {
            return url;
        }
    }

    public void addFragment(String fragment) {
        if (!hasQuery) {
            url += "#";
            hasQuery = true;
        }
        url += fragment;
    }
}

public class UrlBuilderTest {

    @Test
    public void testBuildUrl() {
        UrlBuilder urlBuilder = new UrlBuilder("https://example.com");
        urlBuilder.addQueryParameter("key", "value");
        assertEquals("https://example.com?key=value", urlBuilder.build());
    }

    @Test
    public void testBuildUrlWithFragment() {
        UrlBuilder urlBuilder = new UrlBuilder("https://example.com");
        urlBuilder.addQueryParameter("key", "value");
        urlBuilder.addFragment("fragmentKey=fragmentValue");
        assertEquals("https://example.com?key=value#fragmentKey=fragmentValue", urlBuilder.build());
    }
}
